
const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Headers":
        "authorization, x-client-info, apikey, content-type",
          "Access-Control-Allow-Methods": "POST, OPTIONS",
          };

          Deno.serve(async (req: Request): Promise<Response> => {
            const respond = (body: unknown, status = 200) =>
                new Response(JSON.stringify(body), {
                      status,
                            headers: {
                                    ...corsHeaders,
                                            "Content-Type": "application/json",
                                                  },
                                                      });

                                                        if (req.method === "OPTIONS") {
                                                            return new Response("ok", { headers: corsHeaders });
                                                              }

                                                                if (req.method !== "POST") {
                                                                    return respond({ error: "Only POST requests are allowed." }, 405);
                                                                      }

                                                                        try {
                                                                            // Read the server-side secrets.
                                                                                const supabaseUrl = Deno.env.get("SUPABASE_URL");
                                                                                    const supabaseAnonKey = Deno.env.get("SUPABASE_ANON_KEY");
                                                                                        const openaiKey = Deno.env.get("OPENAI_API_KEY");

                                                                                            if (!supabaseUrl || !supabaseAnonKey || !openaiKey) {
                                                                                                  console.error("A required server secret is missing.");
                                                                                                        return respond({ error: "BRITUME AI is not configured." }, 500);
                                                                                                            }

                                                                                                                // Require a signed-in BRITUME user.
                                                                                                                    const authorization = req.headers.get("Authorization");

                                                                                                                        if (!authorization?.startsWith("Bearer ")) {
                                                                                                                              return respond(
                                                                                                                                      { error: "Please sign in to BRITUME first." },
                                                                                                                                              401
                                                                                                                                                    );
                                                                                                                                                        }

                                                                                                                                                            // Verify the user's Supabase session.
                                                                                                                                                                const authResponse = await fetch(
                                                                                                                                                                      `${supabaseUrl}/auth/v1/user`,
                                                                                                                                                                            {
                                                                                                                                                                                    method: "GET",
                                                                                                                                                                                            headers: {
                                                                                                                                                                                                      Authorization: authorization,
                                                                                                                                                                                                                apikey: supabaseAnonKey,
                                                                                                                                                                                                                        },
                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                      if (!authResponse.ok) {
                                                                                                                                                                                                                                            return respond(
                                                                                                                                                                                                                                                    { error: "Your session is invalid or expired. Please sign in again." },
                                                                                                                                                                                                                                                            401
                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                          const user = await authResponse.json();

                                                                                                                                                                                                                                                                              if (!user?.id) {
                                                                                                                                                                                                                                                                                    return respond(
                                                                                                                                                                                                                                                                                            { error: "Could not verify your BRITUME account." },
                                                                                                                                                                                                                                                                                                    401
                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                  // Read and validate the message.
                                                                                                                                                                                                                                                                                                                      let body: Record<string, unknown>;

                                                                                                                                                                                                                                                                                                                          try {
                                                                                                                                                                                                                                                                                                                                body = await req.json();
                                                                                                                                                                                                                                                                                                                                    } catch {
                                                                                                                                                                                                                                                                                                                                          return respond({ error: "Invalid JSON request." }, 400);
                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                  const message =
                                                                                                                                                                                                                                                                                                                                                        typeof body.message === "string" ? body.message.trim() : "";

                                                                                                                                                                                                                                                                                                                                                            if (
                                                                                                                                                                                                                                                                                                                                                                  body.user_id !== undefined &&
                                                                                                                                                                                                                                                                                                                                                                        body.user_id !== user.id
                                                                                                                                                                                                                                                                                                                                                                            ) {
                                                                                                                                                                                                                                                                                                                                                                                  return respond({ error: "Account verification failed." }, 403);
                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                          if (!message || message.length > 8000) {
                                                                                                                                                                                                                                                                                                                                                                                                return respond(
                                                                                                                                                                                                                                                                                                                                                                                                        { error: "Message must contain between 1 and 8000 characters." },
                                                                                                                                                                                                                                                                                                                                                                                                                400
                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                              // Send the message to OpenAI.
                                                                                                                                                                                                                                                                                                                                                                                                                                  const controller = new AbortController();
                                                                                                                                                                                                                                                                                                                                                                                                                                      const timeout = setTimeout(() => controller.abort(), 45000);

                                                                                                                                                                                                                                                                                                                                                                                                                                          let openaiResponse: Response;

                                                                                                                                                                                                                                                                                                                                                                                                                                              try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                    openaiResponse = await fetch(
                                                                                                                                                                                                                                                                                                                                                                                                                                                            "https://api.openai.com/v1/chat/completions",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              method: "POST",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        headers: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Authorization: `Bearer ${openaiKey}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Content-Type": "application/json",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    body: JSON.stringify({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                model: "gpt-4o-mini",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            messages: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          role: "system",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          content:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "You are BRITUME AI, the helpful AI assistant inside BRITUME — Vortex of Possibilities. " +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "Be friendly, respectful, intelligent, creative and clear. " +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Help users with learning, business plans, coding, research, " +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "writing, creativity and everyday questions. " +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "Understand that BRITUME serves Botswana and users around the world. " +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "Never claim to have performed an action you have not performed.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  role: "user",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  content: message,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        max_completion_tokens: 800,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            signal: controller.signal,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } finally {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    clearTimeout(timeout);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const result = await openaiResponse.json();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!openaiResponse.ok) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      console.error(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "OpenAI request failed:",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      openaiResponse.status,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              result?.error?.code || "Unknown error"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return respond(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            error:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "BRITUME AI could not generate a response. Please try again.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        502
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const reply =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            result.choices?.[0]?.message?.content?.trim();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (typeof reply !== "string" || !reply) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return respond(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              { error: "BRITUME AI returned an empty response." },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      502
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return respond({ reply });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          console.error("rapid-function error:", error);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (error instanceof Error && error.name === "AbortError") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return respond(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            { error: "BRITUME AI took too long to respond. Please try again." },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    504
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return respond(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        { error: "Something went wrong. Please try again." },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              500
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    